// Extract data from TradingView alert
const tvData = $input.first().json;

// Parse TradingView message
const symbol = (tvData.symbol || tvData.ticker || 'BBCA').toUpperCase();
const price = parseFloat(tvData.close || tvData.price || 9850);
const volume = parseInt(tvData.volume || 1000000);
const timeframe = tvData.timeframe || tvData.interval || '1D';

// Get chart screenshot URL (if provided)
const chartUrl = tvData.screenshot_url || tvData.chart_url || '';

return {
  json: {
    symbol: symbol,
    price: price,
    volume: volume,
    timeframe: timeframe,
    chartUrl: chartUrl,
    rawData: tvData,
    timestamp: new Date().toISOString()
  }
};

