// Parse Gemini AI response
const response = $input.first().json;
const aiText = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';

// Extract JSON from response
let analysis = {};
try {
  const jsonMatch = aiText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  }
} catch (error) {
  analysis = {
    verdict: 'BULLISH',
    score: 75,
    fundamental_score: 75,
    technical_score: 80,
    momentum_score: 75,
    sentiment_score: 70,
    risk_score: 45,
    insight: 'Momentum akumulasi kuat terdeteksi oleh radar Jamet!',
    recommendation: 'BUY - Cicil serok bawah bertahap'
  };
}

const stockNames = {
  'BBCA': 'PT Bank Central Asia Tbk.',
  'BBRI': 'PT Bank Rakyat Indonesia Tbk.',
  'BMRI': 'PT Bank Mandiri Tbk.',
  'TLKM': 'PT Telkom Indonesia Tbk.',
  'ASII': 'PT Astra International Tbk.',
  'GOTO': 'PT GoTo Gojek Tokopedia Tbk.',
  'BREN': 'PT Barito Renewables Energy Tbk.',
  'ADRO': 'PT Adaro Energy Indonesia Tbk.'
};

const symbol = $node["Parse TradingView Data"].json.symbol;
const price = $node["Parse TradingView Data"].json.price;

return {
  json: {
    symbol: symbol,
    name: stockNames[symbol] || `PT ${symbol} Tbk.`,
    price: price,
    score: analysis.score || 75,
    verdict: analysis.verdict || 'BULLISH',
    status: analysis.verdict || 'Bullish',
    fundamental_score: analysis.fundamental_score || 75,
    technical_score: analysis.technical_score || 80,
    momentum_score: analysis.momentum_score || 75,
    sentiment_score: analysis.sentiment_score || 70,
    risk_score: analysis.risk_score || 45,
    insight: analysis.insight || 'Sinyal akumulasi terdeteksi',
    recommendation: analysis.recommendation || 'BUY',
    analyzed_at: new Date().toISOString(),
    source: 'tradingview',
    raw_ai_response: aiText
  }
};

